// src/lib/downloadHelper.ts
async function downloadApkSafely(filename = "DentalCare.apk", onProgress) {
	try {
		const targetUrl = `./${filename}?v=${Date.now()}`;
		const response = await fetch(targetUrl, {
			method: "GET",
			headers: { "Accept": "application/vnd.android.package-archive,application/octet-stream,*/*" }
		});
		if (response.status === 403) return {
			success: false,
			error: "خطای ۴۰۳ (عدم دسترسی به فایل از طریق پراکسی گوگل استودیو)",
			is403Forbidden: true
		};
		if (!response.ok) return {
			success: false,
			error: `خطای سرور (${response.status} ${response.statusText})`,
			is403Forbidden: response.status === 403
		};
		const contentLength = response.headers.get("content-length");
		const totalBytes = contentLength ? parseInt(contentLength, 10) : 0;
		let blob;
		if (response.body && totalBytes > 0 && onProgress) {
			const reader = response.body.getReader();
			const chunks = [];
			let receivedBytes = 0;
			while (true) {
				const { done, value } = await reader.read();
				if (done) break;
				if (value) {
					chunks.push(value);
					receivedBytes += value.length;
					onProgress(Math.min(99, Math.round(receivedBytes / totalBytes * 100)));
				}
			}
			blob = new Blob(chunks, { type: "application/vnd.android.package-archive" });
			onProgress(100);
		} else {
			blob = await response.blob();
			if (onProgress) onProgress(100);
		}
		const blobUrl = URL.createObjectURL(blob);
		const link = document.createElement("a");
		link.href = blobUrl;
		link.download = filename;
		document.body.appendChild(link);
		link.click();
		document.body.removeChild(link);
		setTimeout(() => {
			URL.revokeObjectURL(blobUrl);
		}, 6e4);
		return { success: true };
	} catch (err) {
		const errMsg = err?.message || String(err);
		return {
			success: false,
			error: errMsg,
			is403Forbidden: errMsg.includes("403") || errMsg.includes("Forbidden")
		};
	}
}
