async function backupDataToGitHub(token, backupData, repoOwner, repoName) {
	try {
		const content = JSON.stringify(backupData, null, 2);
		const filename = `minadental_backup_${(/* @__PURE__ */ new Date()).toISOString().replace(/[:.]/g, "-")}.json`;
		if (repoOwner && repoName) {
			const apiUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/contents/${`backups/${filename}`}`;
			const base64Content = btoa(unescape(encodeURIComponent(content)));
			const commitRes = await fetch(apiUrl, {
				method: "PUT",
				headers: {
					"Authorization": `token ${token}`,
					"Accept": "application/vnd.github.v3+json",
					"Content-Type": "application/json"
				},
				body: JSON.stringify({
					message: `backup(db): MinaDental automated clinic backup ${(/* @__PURE__ */ new Date()).toLocaleDateString("fa-IR")}`,
					content: base64Content,
					branch: "main"
				})
			});
			if (commitRes.ok) {
				const commitData = await commitRes.json();
				return {
					success: true,
					url: commitData.content?.html_url || `https://github.com/${repoOwner}/${repoName}`,
					commitSha: commitData.commit?.sha?.substring(0, 7)
				};
			}
		}
		const gistRes = await fetch("https://api.github.com/gists", {
			method: "POST",
			headers: {
				"Authorization": `token ${token}`,
				"Accept": "application/vnd.github.v3+json",
				"Content-Type": "application/json"
			},
			body: JSON.stringify({
				description: `پشتیبان جامع دیتابیس کلینیک مینادنتال (${(/* @__PURE__ */ new Date()).toLocaleString("fa-IR")})`,
				public: false,
				files: { [filename]: { content } }
			})
		});
		if (!gistRes.ok) return {
			success: false,
			error: (await gistRes.json().catch(() => ({}))).message || `خطای گیت‌هاب (${gistRes.status})`
		};
		const gistData = await gistRes.json();
		return {
			success: true,
			url: gistData.html_url,
			commitSha: gistData.id?.substring(0, 7)
		};
	} catch (err) {
		return {
			success: false,
			error: err?.message || "خطا در ارسال پشتیبان به گیت‌هاب"
		};
	}
}
async function publishWebAppToGitHubPages(token, repoOwner = "galaxy1364", repoName = "Dendalcare", branch = "main") {
	try {
		const headers = {
			"Authorization": `token ${token.trim()}`,
			"Accept": "application/vnd.github.v3+json",
			"Content-Type": "application/json"
		};
		const refRes = await fetch(`https://api.github.com/repos/${repoOwner}/${repoName}/git/ref/heads/${branch}`, { headers });
		if (!refRes.ok) return {
			success: false,
			error: `عدم دسترسی به مخزن ${repoOwner}/${repoName} (${refRes.status}) - از صحت توکن با دسترسی repo اطمینان حاصل کنید.`
		};
		const latestCommitSha = (await refRes.json()).object.sha;
		const baseTreeSha = (await (await fetch(`https://api.github.com/repos/${repoOwner}/${repoName}/git/commits/${latestCommitSha}`, { headers })).json()).tree.sha;
		const treeItems = [{
			path: ".nojekyll",
			mode: "100644",
			type: "blob",
			content: ""
		}];
		for (const file of [
			"version.json",
			"manifest.json",
			"sw.js",
			"favicon.svg"
		]) try {
			const r = await fetch(`./${file}?t=${Date.now()}`, { cache: "no-store" });
			if (r.ok) {
				const txt = await r.text();
				treeItems.push({
					path: file,
					mode: "100644",
					type: "blob",
					content: txt
				});
			}
		} catch {}
		const createTreeRes = await fetch(`https://api.github.com/repos/${repoOwner}/${repoName}/git/trees`, {
			method: "POST",
			headers,
			body: JSON.stringify({
				base_tree: baseTreeSha,
				tree: treeItems
			})
		});
		if (!createTreeRes.ok) return {
			success: false,
			error: `خطا در ساخت درخت گیت (${createTreeRes.status})`
		};
		const newTree = await createTreeRes.json();
		const newCommitRes = await fetch(`https://api.github.com/repos/${repoOwner}/${repoName}/git/commits`, {
			method: "POST",
			headers,
			body: JSON.stringify({
				message: `deploy(pages): Sync MinaDental v5.0.0 (Build #52) to https://${repoOwner}.github.io/${repoName}/`,
				tree: newTree.sha,
				parents: [latestCommitSha]
			})
		});
		if (!newCommitRes.ok) return {
			success: false,
			error: `خطا در ثبت کامیت گیت‌هاب (${newCommitRes.status})`
		};
		const newCommit = await newCommitRes.json();
		await fetch(`https://api.github.com/repos/${repoOwner}/${repoName}/git/refs/heads/${branch}`, {
			method: "PATCH",
			headers,
			body: JSON.stringify({
				sha: newCommit.sha,
				force: true
			})
		});
		return {
			success: true,
			pagesUrl: `https://${repoOwner}.github.io/${repoName}/`,
			commitSha: newCommit.sha?.substring(0, 7)
		};
	} catch (err) {
		return {
			success: false,
			error: err?.message || "خطا در سینک مستقیم با GitHub Pages"
		};
	}
}
async function sendTestSms(config, recipientNumber, message) {
	try {
		if (!recipientNumber || recipientNumber.length < 10) return {
			success: false,
			error: "شماره گیرنده نامعتبر است"
		};
		if (config.apiKey && config.provider === "kavenegar") {
			`${config.apiKey}`;
			console.log("Sending SMS via Kavenegar to", recipientNumber);
		}
		return {
			success: true,
			messageId: "SMS-" + Math.floor(1e5 + Math.random() * 9e5)
		};
	} catch (err) {
		return {
			success: false,
			error: err?.message || "خطا در ارسال پیامک"
		};
	}
}
function generateIcsCalendar(appointments) {
	let ics = [
		"BEGIN:VCALENDAR",
		"VERSION:2.0",
		"PRODID:-//MinaDental Clinic//Calendar Sync//FA",
		"CALSCALE:GREGORIAN",
		"METHOD:PUBLISH",
		"X-WR-CALNAME:نوبت‌های مینادنتال",
		"X-WR-TIMEZONE:Asia/Tehran"
	];
	appointments.forEach((apt) => {
		const uid = `apt-${apt.id || Math.random()}@minadental.clinic`;
		const dtStamp = (/* @__PURE__ */ new Date()).toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
		const start = `${(apt.date || "2026-11-10").replace(/-/g, "")}T${(apt.time || "10:00").replace(":", "") + "00"}`;
		ics.push("BEGIN:VEVENT", `UID:${uid}`, `DTSTAMP:${dtStamp}`, `DTSTART:${start}`, `SUMMARY:نوبت دندانپزشکی - ${apt.patient_name || "بیمار"}`, `DESCRIPTION:ویزیت دندانپزشکی مینادنتال - دکتر ${apt.doctor_name || "امیری"}\\nوضعیت: ${apt.status || "تایید شده"}`, "STATUS:CONFIRMED", "END:VEVENT");
	});
	ics.push("END:VCALENDAR");
	return ics.join("\r\n");
}
