String.prototype.toPersianDigits = function() {
	const persian = [
		"۰",
		"۱",
		"۲",
		"۳",
		"۴",
		"۵",
		"۶",
		"۷",
		"۸",
		"۹"
	];
	return this.replace(/[0-9]/g, (d) => persian[parseInt(d)]);
};
